pub fn minimum_deletions(nums: Vec<i32>) -> i32 {
    if nums.len() == 1 {
        return 1;
    }

    let mut min_index = 0;
    let mut max_index = 0;

    for i in 1..nums.len() {
        if nums[i] < nums[min_index] {
            min_index = i;
        }
        if nums[i] > nums[max_index] {
            max_index = i;
        }
    }

    let mut deletions = 0;

    if min_index < max_index {
        deletions = std::cmp::min(min_index + 1, nums.len() - max_index);
    } else {
        deletions = std::cmp::min(max_index + 1, nums.len() - min_index);
    }

    deletions
}
